/** Generic note for politics pairs not individually judged (seed/fuzzy). */
const GENERIC_POLITICS: Divergence = {
  status: "minor",
  confidence: 0.5,
  reasoning:
    "Resolution rules for this pair have not been individually verified. Election markets commonly diverge on who decides (a named source vs a ‘credible reporting’ consensus), candidate death/withdrawal, and ‘wins’ vs ‘inaugurated’ timing.",
  divergenceCases: [
    "Different sources of truth between venues can disagree in a contested result.",
    "Death / withdrawal / replacement of the subject is handled differently (Kalshi often last-price; Polymarket can pay full $1).",
  ],
  worstCase:
    "Until both venues' rules are confirmed identical, treat the worst case as both legs losing rather than a locked spread.",
};

/** Look up the resolution-equivalence assessment for a pair. */
export function divergenceFor(pairId: string, category: string): Divergence | null {
  if (pairId.startsWith("event:")) {
    const key = pairId.split(":")[1];
    if (DIVERGENCE_BY_EVENT[key]) return DIVERGENCE_BY_EVENT[key];
  }
  if (category === "Politics") return GENERIC_POLITICS;
  return null;
}
